/** Explicit protocol adapter. No full-gate receipt is created or rewritten. */
import{readFileSync}from'node:fs';import{resolve}from'node:path';import{fileURLToPath}from'node:url';import{operatorRelease}from'./operator-release.mjs';import{verifyTypeRepairCi}from'./verify-type-repair.mjs';import{createTypeRepairInstallGrant}from'./build-only-evidence.mjs';
export async function operatorTypeRepair({candidatePath,plan,execute=false}){let verified;
 const evidenceProtocol={kind:'type-only-test-fixture-repair/v1',verify:async options=>{verified=await verifyTypeRepairCi({...options,plan});return verified.evidence;},revalidate:async evidence=>{if(evidence!==verified?.evidence)throw Error('Combined evidence identity changed');return verified.revalidate();},createGrant:({evidence,baselineBuildId,environmentSha256})=>{if(evidence!==verified?.evidence)throw Error('Combined evidence identity changed');return createTypeRepairInstallGrant({acceptance:evidence.acceptance,evidence,snapshot:verified.snapshot,baselineBuildId,environmentSha256});}};
 return operatorRelease({candidatePath,execute,evidenceProtocol});
}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url)){const[mode,candidatePath,planFile]=process.argv.slice(2);if(process.argv.length!==5||!['verify','deploy'].includes(mode))throw Error('Usage: operator-type-repair.mjs <verify|deploy> <clean-candidate> <private-plan.json>');operatorTypeRepair({candidatePath,plan:JSON.parse(readFileSync(planFile)),execute:mode==='deploy'}).then(result=>{console.log(JSON.stringify(result,null,2));process.exit(0);}).catch(error=>{console.error(error);process.exitCode=1;});}
